const item = $input.item.json;
const output = item.output || [];

const results = {
  total: output.length,
  successful: 0,
  failed: 0,
  errors: [],
  successes: []
};

output.forEach((result, index) => {
  if (result.error) {
    results.failed++;
    results.errors.push({
      index: index,
      message: result.error.message,
      code: result.error.code,
      status: result.error.status
    });
  } else if (result.success) {
    results.successful++;
    results.successes.push({
      index: index,
      message: result.message
    });
  }
});

return {
  summary: results,
  allSucceeded: results.failed === 0,
  allFailed: results.successful === 0
};
